contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}();
        uint balBefore = c.getBalance(address(this));
        uint ethBefore = address(this).balance;
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
