contract InvMutTest {
    C c;
    bool rejectPayments;

    constructor(C _c) { c = _c; rejectPayments = false; }

    function run(uint amount, bool failWithdraw) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // fund c's ETH balance via a deposit
        c.addToBalance{value: amount}();

        uint balBefore = c.getBalance(address(this));
        uint ethBefore = address(c).balance;

        rejectPayments = failWithdraw;

        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }

        rejectPayments = false;

        if (failWithdraw) {
            assert(reverted && c.getBalance(address(this)) == balBefore && address(c).balance == ethBefore);
        } else {
            assert(!reverted && c.getBalance(address(this)) == 0);
        }
    }

    receive() external payable {
        if (rejectPayments) { revert(); }
    }
}

